    {'subject_name': 'Algebra', 'subject_code': 'algebra', 'grade': 10, 'quarter': 1, 'chapter': 'Funksiyalar va Trigonometriya', 'topics': [{'title': "Haqiqiy sonlar to'plami. Funksiya, uning aniqlanish va qiymatlar sohasi", 'objectives': "Murakkab funksiyalarning aniqlanish sohasini to'g'ri topish."}, {'title': 'Funksiyaning juft va toqligi. Monotonlik oraliqlari', 'objectives': 'f(-x) = f(x) va f(-x) = -f(x) shartlarini tekshirish, grafik simmetriyasi.'}, {'title': 'Davriy funksiyalar va eng kichik musbat davr', 'objectives': 'Trigonometrik funksiyalarning davrini hisoblash.'}, {'title': 'Teskari funksiya tushunchasi', 'objectives': 'y = f(x) funksiyaga teskari funksiyani topish va grafiklarini taqqoslash.'}, {'title': 'y = sin x va y = cos x funksiyalari, ularning xossalari va grafiklari', 'objectives': "Sinusoida va kosinusoida to'lqinlarini chizish, asosiy xossalarini tahlil qilish."}, {'title': 'y = tg x va y = ctg x funksiyalari, ularning xossalari va grafiklari', 'objectives': 'Uzluksizlik oraliqlari va asimptotalarni aniqlash.'}, {'title': 'Trigonometrik funksiyalarning grafiklarini almashtirishlar', 'objectives': "y = A sin(kx + b) funksiya grafigini koordinata o'qlari bo'yicha siljitish va cho'zish."}]},
    {'subject_name': 'Algebra', 'subject_code': 'algebra', 'grade': 10, 'quarter': 2, 'chapter': 'Trigonometrik tenglamalar va ayniyatlar', 'topics': [{'title': "Trigonometrik funksiyalar yig'indisi va ayirmasini ko'paytmaga keltirish", 'objectives': "sin α ± sin β va cos α ± cos β formulalarini ifodalarni soddalashtirishda qo'llash."}, {'title': "Ko'paytmani yig'indiga almashtirish formulalari", 'objectives': "sin α * cos β va boshqa ko'paytmalarni yig'indiga aylantirish."}, {'title': 'Eng sodda trigonometrik tenglamalar: sin x = a va cos x = a', 'objectives': 'Umumiy yechimlar formulalari (x = (-1)^k arcsin a + πk, x = ± arccos a + 2πk) bilan ishlash.'}, {'title': 'Eng sodda trigonometrik tenglamalar: tg x = a va ctg x = a', 'objectives': 'x = arctg a + πk formulasidan foydalanish.'}, {'title': 'Bir jinsli trigonometrik tenglamalar va ularni yechish usullari', 'objectives': "cos^2 x ga yoki cos x ga bo'lish orqali tangensga nisbatan kvadrat tenglamaga keltirish."}, {'title': 'Trigonometrik tengsizliklar va ularni birlik aylanada yechish', 'objectives': "sin x > a, cos x < a ko'rinishidagi tengsizliklarni oraliqlar bo'yicha yechish."}]},
    {'subject_name': 'Algebra', 'subject_code': 'algebra', 'grade': 10, 'quarter': 3, 'chapter': 'Darajali funksiya va Irratsional tenglamalar', 'topics': [{'title': "Haqiqiy ko'rsatkichli daraja va uning xossalari", 'objectives': 'a^(m/n) = n-darajali ildiz (a^m) munosabatidan foydalanish.'}, {'title': 'n-darajali arifmetik ildiz va uning asosiy xossalari', 'objectives': 'Ildizlar ustida algebraik amallarni bajarish va darajalarni qisqartirish.'}, {'title': 'Irratsional ifodalarni ayniy shakl almashtirishlar', 'objectives': "Kasr maxrajidagi irratsionallikni yo'qotish (qo'shmasiga ko'paytirish)."}, {'title': "Irratsional tenglamalar va ularni kvadratga ko'tarish usuli", 'objectives': "Tenglamani darajaga ko'tarishda chet ildizlar paydo bo'lishini tekshirish."}, {'title': "Yangi o'zgaruvchi kiritish usuli bilan irratsional tenglamalarni yechish", 'objectives': 'Murakkab irratsional tenglamalarni soddalashtirish.'}, {'title': 'Irratsional tengsizliklar va ularni oraliqlar usulida yechish', 'objectives': 'Aniqlanish sohasini inobatga olgan holda tengsizliklarni yechish.'}]},
    {'subject_name': 'Algebra', 'subject_code': 'algebra', 'grade': 10, 'quarter': 4, 'chapter': "Ko'rsatkichli va Logarifmik funksiyalar", 'topics': [{'title': "Ko'rsatkichli funksiya y = a^x (a > 0, a != 1), uning xossalari va grafigi", 'objectives': "a > 1 da o'suvchi, 0 < a < 1 da kamayuvchi ekanligini bilish."}, {'title': "Ko'rsatkichli tenglamalar va ularni bir xil asosga keltirish usuli", 'objectives': 'a^(f(x)) = a^(g(x)) tenglamani f(x) = g(x) ga keltirib yechish.'}, {'title': "Ko'rsatkichli tenglamalarni yangi o'zgaruvchi kiritish usuli bilan yechish", 'objectives': "Kvadrat tenglamaga keltiriladigan ko'rsatkichli tenglamalar."}, {'title': "Ko'rsatkichli tengsizliklar", 'objectives': "Asos 1 dan katta yoki kichikligiga qarab tengsizlik ishorasini to'g'ri tanlash."}, {'title': "Logarifm ta'rifi va asosiy logarifmik ayniyat: a^(log_a b) = b", 'objectives': "Logarifmning ma'nosini tushunish va hisoblash."}, {'title': "Logarifmning asosiy xossalari (ko'paytma, bo'linma, daraja logarifmi)", 'objectives': "Logarifmik ifodalarni soddalashtirish va yangi asosga o'tish formulasi."}, {'title': 'Logarifmik tenglamalar: log_a f(x) = log_a g(x)', 'objectives': 'Aniqlanish sohasini (f(x) > 0, g(x) > 0) hisobga olib tenglamalarni yechish.'}]},
    {'subject_name': 'Algebra', 'subject_code': 'algebra', 'grade': 11, 'quarter': 1, 'chapter': "Hosila va uning qo'llanilishi", 'topics': [{'title': 'Logarifmik tengsizliklar va ularning sistemalari', 'objectives': "Asosga qarab logarifmik tengsizliklarni to'g'ri yechish."}, {'title': "Hosilaning ta'rifi. Funksiya orttirmasi va argument orttirmasi", 'objectives': "Hosilaning chegaraviy ma'nosini tushunish: f'(x) = lim (Δy/Δx)."}, {'title': "Hosilani hisoblashning asosiy qoidalari: Yig'indi, ko'paytma va bo'linma", 'objectives': "(u+v)', (u*v)', (u/v)' formulalarini to'g'ri qo'llash."}, {'title': "Darajali, ko'rsatkichli va logarifmik funksiyalarning hosilasi", 'objectives': "(x^n)', (e^x)', (a^x)', (ln x)' hosilalarini hisoblash."}, {'title': 'Trigonometrik funksiyalarning hosilasi', 'objectives': "(sin x)' = cos x, (cos x)' = -sin x formulalaridan foydalanish."}, {'title': 'Murakkab funksiya hosilasi', 'objectives': "(f(g(x)))' = f'(g(x)) * g'(x) zanjir qoidasini qo'llash."}]},
    {'subject_name': 'Algebra', 'subject_code': 'algebra', 'grade': 11, 'quarter': 2, 'chapter': 'Hosilaning tatbiqlari va Funksiyani tekshirish', 'topics': [{'title': "Hosilaning geometrik ma'nosi. Urinma tenglamasi", 'objectives': "y = f(x_0) + f'(x_0)(x - x_0) urinma tenglamasini tuzish."}, {'title': "Hosilaning mexanik (fizik) ma'nosi: Lahzali tezlik va tezlanish", 'objectives': "v(t) = s'(t) va a(t) = v'(t) formulalari orqali masalalar yechish."}, {'title': "Funksiyaning o'sish va kamayish oraliqlarini hosila yordamida aniqlash", 'objectives': "f'(x) > 0 da funksiya o'suvchi, f'(x) < 0 da kamayuvchi ekanligini qo'llash."}, {'title': 'Funksiyaning kritik va statsionar nuqtalari. Ekstremumlar', 'objectives': "f'(x) = 0 tenglamadan maksimum va minimum nuqtalarni aniqlash."}, {'title': 'Funksiyaning berilgan kesmadagi eng katta va eng kichik qiymatlarini topish', 'objectives': 'Kritik nuqtalardagi va kesma chetlaridagi qiymatlarni taqqoslash.'}, {'title': "Hosila yordamida funksiyani to'liq tekshirish va grafigini yasash", 'objectives': "Funksiya grafigini barcha bosqichlar bo'yicha chizish madaniyati."}]},
    {'subject_name': 'Algebra', 'subject_code': 'algebra', 'grade': 11, 'quarter': 3, 'chapter': 'Integral va uning tatbiqlari', 'topics': [{'title': "Boshlang'ich funksiya tushunchasi va aniqmas integral", 'objectives': "F'(x) = f(x) munosabatini va C integrallash doimiysini bilish."}, {'title': "Boshlang'ich funksiyalarni topish qoidalari va integrallar jadvali", 'objectives': "Asosiy funksiyalarning boshlang'ich shakllarini jadvaldan topish."}, {'title': 'Aniq integral tushunchasi. Nyuton-Leybnits formulasi', 'objectives': '∫[a,b] f(x)dx = F(b) - F(a) formulasidan foydalanib hisoblash.'}, {'title': 'Aniq integralning asosiy xossalari', 'objectives': "Integrallash oraliqlarini bo'lish va ko'paytuvchini chiqarish xossalarini qo'llash."}, {'title': 'Egri chiziqli trapetsiyaning yuzini aniq integral yordamida hisoblash', 'objectives': 'Funksiya grafiklari bilan chegaralangan sohalar yuzasini topish.'}, {'title': 'Aylanish jismlarining hajmini integral yordamida hisoblash', 'objectives': "V = π ∫ y^2 dx formulasini qo'llab hajmni aniqlash."}]},
    {'subject_name': 'Algebra', 'subject_code': 'algebra', 'grade': 11, 'quarter': 4, 'chapter': 'Matematik mantiq va Umumlashtiruvchi takrorlash', 'topics': [{'title': "To'plamlar nazariyasi va matematik mantiq elementlari", 'objectives': 'Dizyunksiya, konyunksiya va inkor amallarini bilish.'}, {'title': 'Tasodifiy miqdorlar va ularning taqsimot qonunlari', 'objectives': 'Matematik kutilma va dispersiya tushunchalari bilan tanishish.'}, {'title': "Matematik statistika elementlari: Tanlanma, o'rta qiymat, moda va mediana", 'objectives': "Statistik ma'lumotlarni tahlil qilish."}, {'title': 'Matematikadan Davlat attestatsiyasi va OTM imtihonlariga tayyorgarlik', 'objectives': "Murakkab test va amaliy masalalarni tezkor yechish ko'nikmalari."}]},
    {'subject_name': 'Geometriya', 'subject_code': 'geometriya', 'grade': 7, 'quarter': 1, 'chapter': "Boshlang'ich geometrik tushunchalar", 'topics': [{'title': "Nuqta, to'g'ri chiziq, nur va kesma", 'objectives': "Asosiy geometrik figuralarning ta'rifi va chizish qoidalarini bilish."}, {'title': "Burchak turlari: o'tkir, to'g'ri, o'tmas va yoyiq burchaklar", 'objectives': "Burchaklarni transportir bilan o'lchash va ularni taqqoslash."}, {'title': "Qo'shni va vertikal burchaklar xossalari", 'objectives': "Qo'shni burchaklar yig'indisi 180 gradus ekanligini hisob-kitoblarda qo'llash."}, {'title': 'Uchburchaklar tengligining birinchi alomati', 'objectives': "Ikki tomon va ular orasidagi burchak bo'yicha tenglikni isbotlash."}]},
    {'subject_name': 'Geometriya', 'subject_code': 'geometriya', 'grade': 7, 'quarter': 2, 'chapter': 'Uchburchaklar tenglik alomatlari', 'topics': [{'title': 'Uchburchakning medianasi, bissektrisasi va balandligi', 'objectives': 'Asosiy chiziqlarni yasash va xossalarini bilish.'}, {'title': 'Teng yonli uchburchak va uning xossalari', 'objectives': 'Asosidagi burchaklar tengligi va asosga tushirilgan bissektrisa xossasi.'}, {'title': 'Uchburchaklar tengligining ikkinchi va uchinchi alomatlari', 'objectives': "Tomon va unga yopishgan ikki burchak hamda uch tomon bo'yicha tenglik."}, {'title': 'Aylana va doira. Markaz, radius, vatar va diametr', 'objectives': 'Sirkul yordamida geometrik yasashlarni bajarish.'}]},
    {'subject_name': 'Geometriya', 'subject_code': 'geometriya', 'grade': 7, 'quarter': 3, 'chapter': "Parallel to'g'ri chiziqlar", 'topics': [{'title': "Parallel to'g'ri chiziqlar ta'rifi va aksiomasi", 'objectives': "Yevklid aksiomasi va to'g'ri chiziqlar parallelligi belgilarini bilish."}, {'title': "Ikki to'g'ri chiziqni uchinchi to'g'ri chiziq bilan kesganda hosil bo'lgan burchaklar", 'objectives': 'Ichki bir tomonli, ichki almashinuvchi va mos burchaklar.'}, {'title': "To'g'ri chiziqlarning parallellik alomatlari", 'objectives': 'Ichki almashinuvchi burchaklar tengligi orqali parallellikni isbotlash.'}, {'title': "Uchburchak ichki burchaklarining yig'indisi haqidagi teorema", 'objectives': "Har qanday uchburchak burchaklari yig'indisi 180 gradus ekanligini qo'llash."}]},
    {'subject_name': 'Geometriya', 'subject_code': 'geometriya', 'grade': 7, 'quarter': 4, 'chapter': "To'g'ri burchakli uchburchak va Yasashga doir masalalar", 'topics': [{'title': "To'g'ri burchakli uchburchak va uning xossalari", 'objectives': '30 gradusli burchak qarshisidagi katet gipotenuzaning yarmiga tengligi.'}, {'title': "To'g'ri burchakli uchburchaklar tenglik alomatlari", 'objectives': "Gipotenuza va o'tkir burchak, katetlar bo'yicha tenglik."}, {'title': 'Uchburchak tengsizligi', 'objectives': "Har qanday tomon qolgan ikki tomon yig'indisidan kichikligini tekshirish."}, {'title': "Sirkul va chizg'ich yordamida yasashga doir masalalar", 'objectives': "Burchak bissektrisasini va kesma o'rtasini yasash."}]},
    {'subject_name': 'Geometriya', 'subject_code': 'geometriya', 'grade': 8, 'quarter': 1, 'chapter': "To'rtburchaklar", 'topics': [{'title': "Ko'pburchaklar va qavariq ko'pburchaklar", 'objectives': "Qavariq ko'pburchak ichki burchaklari yig'indisi formulasi: (n-2)*180."}, {'title': "Parallelogramm ta'rifi va xossalari", 'objectives': 'Qarama-qarshi tomonlar va burchaklar tengligi, diagonallar kesishish xossasi.'}, {'title': 'Parallelogramm alomatlari', 'objectives': "To'rtburchakning parallelogramm ekanligini isbotlash."}, {'title': "Trapetsiya va uning turlari. Teng yonli va to'g'ri burchakli trapetsiya", 'objectives': "Trapetsiyaning o'rta chizig'i xossasini bilish."}, {'title': "To'g'ri to'rtburchak, romb va kvadrat", 'objectives': "Diagonallarning perpendikulyarligi va bissektrisa bo'lishi xossalarini qo'llash."}]},
    {'subject_name': 'Geometriya', 'subject_code': 'geometriya', 'grade': 8, 'quarter': 2, 'chapter': 'Fales teoremasi va Yuzalar', 'topics': [{'title': 'Fales teoremasi va proporsional kesmalar', 'objectives': "Burchak tomonlarini parallel to'g'ri chiziqlar bilan kesish xossasi."}, {'title': "Uchburchakning o'rta chizig'i", 'objectives': "O'rta chiziq asosga parallelligi va uning yarmiga tengligini qo'llash."}, {'title': 'Yuza tushunchasi va yuzaning asosiy xossalari', 'objectives': "Teng shakllar yuzalari tengligi va yuzalar yig'indisi qoidasi."}, {'title': "To'g'ri to'rtburchak va parallelogrammning yuzi", 'objectives': 'S = a * b va S = a * h formulalari bilan hisoblash.'}, {'title': 'Uchburchakning yuzi. Geron formulasi', 'objectives': 'S = 1/2 a*h va yarim perimetr orqali yuzani topish.'}, {'title': 'Romb va trapetsiyaning yuzi', 'objectives': 'S = 1/2 d1*d2 va S = (a+b)/2 * h formulalaridan foydalanish.'}]},
    {'subject_name': 'Geometriya', 'subject_code': 'geometriya', 'grade': 8, 'quarter': 3, 'chapter': 'Pifagor teoremasi va Trigonometrik munosabatlar', 'topics': [{'title': 'Pifagor teoremasi va unga teskari teorema', 'objectives': "c^2 = a^2 + b^2 munosabatini qo'llab gipotenuza va katetlarni hisoblash."}, {'title': 'Pifagor sonlari va Misr uchburchagi', 'objectives': "Uchburchakning to'g'ri burchakli ekanligini tekshirish."}, {'title': "To'g'ri burchakli uchburchakda o'tkir burchak sinusi, kosinusi, tangensi", 'objectives': 'Qarshisidagi katet, yopishgan katet va gipotenuzaga nisbatlar.'}, {'title': '30, 45 va 60 gradusli burchaklarning trigonometrik qiymatlari', 'objectives': "Jadval qiymatlarini masalalar yechishda qo'llash."}]},
    {'subject_name': 'Geometriya', 'subject_code': 'geometriya', 'grade': 8, 'quarter': 4, 'chapter': "Aylana va to'rtburchaklar", 'topics': [{'title': "Aylanaga uringan to'g'ri chiziq va uning xossasi", 'objectives': "Urinma urinish nuqtasiga o'tkazilgan radiusga perpendikulyarligi."}, {'title': 'Markaziy va ichki chizilgan burchaklar', 'objectives': 'Ichki chizilgan burchak tiralgan yoyning yarmiga tengligini bilish.'}, {'title': 'Uchburchakka ichki va tashqi chizilgan aylanalar', 'objectives': "Bissektrisalar va o'rta perpendikulyarlar kesishish nuqtasi."}, {'title': "To'rtburchakka ichki va tashqi chizilgan aylanalar", 'objectives': "Qarama-qarshi tomonlar yig'indisi va burchaklar yig'indisi 180 gradus shartlari."}]},
    {'subject_name': 'Geometriya', 'subject_code': 'geometriya', 'grade': 9, 'quarter': 1, 'chapter': "O'xshash uchburchaklar", 'topics': [{'title': "Proporsional kesmalar va o'xshash figuralar tushunchasi", 'objectives': "Shakllarning o'xshashlik koeffitsiyentini aniqlash."}, {'title': "Uchburchaklar o'xshashligining birinchi alomati (ikki burchak bo'yicha)", 'objectives': "Ikki burchagi teng uchburchaklarning o'xshashligini isbotlash."}, {'title': "Uchburchaklar o'xshashligining ikkinchi va uchinchi alomatlari", 'objectives': 'Ikki tomon proporsionalligi va uch tomon proporsionalligi.'}, {'title': "O'xshash uchburchaklar yuzalari nisbati", 'objectives': "Yuzalar nisbati o'xshashlik koeffitsiyentining kvadratiga tengligini bilish."}]},
    {'subject_name': 'Geometriya', 'subject_code': 'geometriya', 'grade': 9, 'quarter': 2, 'chapter': 'Sinuslar va Kosinuslar teoremalari', 'topics': [{'title': 'Kosinuslar teoremasi: a^2 = b^2 + c^2 - 2bc cos α', 'objectives': "Uxtiyoriy uchburchakning noma'lum tomoni va burchagini hisoblash."}, {'title': 'Sinuslar teoremasi: a/sin A = b/sin B = c/sin C = 2R', 'objectives': 'Tashqi chizilgan aylana radiusi va burchaklarni topish.'}, {'title': 'Ixtiyoriy uchburchaklarni yechish', 'objectives': "Berilgan elementlar bo'yicha uchburchakning barcha tomon va burchaklarini hisoblash."}]},
    {'subject_name': 'Geometriya', 'subject_code': 'geometriya', 'grade': 9, 'quarter': 3, 'chapter': 'Vektorlar va Koordinatalar', 'topics': [{'title': "Vektor tushunchasi. Vektorning uzunligi va yo'nalishi", 'objectives': "Yo'naltirilgan kesma, nol vektor va teng vektorlarni bilish."}, {'title': "Vektorlarni qo'shish va ayirish: Uchburchak va parallelogramm qoidalari", 'objectives': "Vektorlar yig'indisini geometrik yasash."}, {'title': "Vektorni songa ko'paytirish. Kollinear vektorlar", 'objectives': "Vektorlar yo'nalishini va uzunligini aniqlash."}, {'title': 'Vektorning koordinatalari', 'objectives': "Boshlang'ich va oxirgi nuqtalari bo'yicha koordinatalarni hisoblash."}, {'title': "Vektorlarning skalyar ko'paytmasi va ikki vektor orasidagi burchak", 'objectives': 'a * b = |a||b| cos φ va koordinatalar orqali hisoblash.'}]},
    {'subject_name': 'Geometriya', 'subject_code': 'geometriya', 'grade': 9, 'quarter': 4, 'chapter': 'Harakat va Geometrik almashtirishlar', 'topics': [{'title': 'Harakat tushunchasi va uning xossalari', 'objectives': 'Nuqtalar orasidagi masofani saqlovchi almashtirishlar.'}, {'title': "Markaziy simmetriya va o'qqa nisbatan simmetriya", 'objectives': 'Simmetrik nuqta va shakllarni yasash.'}, {'title': "Burish va parallel ko'chirish", 'objectives': "Berilgan burchakka burish va vektor bo'yicha siljitish."}, {'title': "Muntazam ko'pburchaklar va ularning yuzalari", 'objectives': 'Muntazam oltiburchak, aylana uzunligi va doira sektori yuzi.'}]},
    {'subject_name': 'Geometriya', 'subject_code': 'geometriya', 'grade': 10, 'quarter': 1, 'chapter': 'Stereometriya aksiomalari va Parallellik', 'topics': [{'title': "Stereometriyaga kirish. Asosiy tushunchalar: Nuqta, to'g'ri chiziq va tekislik", 'objectives': 'Fazodagi figuralarning tekislikdagi tasvirlanish qoidalari.'}, {'title': 'Stereometriya aksiomalari va ulardan kelib chiqadigan natijalar', 'objectives': 'Tekislikni bir qiymatli aniqlovchi uch nuqta shartini bilish.'}, {'title': "Fazoda ikki to'g'ri chiziqning o'zaro joylashuvi (kesishuvchi, parallel, ayqash)", 'objectives': "Ayqash to'g'ri chiziqlar ta'rifi va alomatini amalda qo'llash."}, {'title': "To'g'ri chiziq va tekislikning parallelligi", 'objectives': "To'g'ri chiziqning tekislikdagi to'g'ri chiziqqa parallelligi alomati."}, {'title': "Tekisliklarning o'zaro parallelligi va alomatlari", 'objectives': "Kesishuvchi ikki to'g'ri chiziqning boshqa tekislikdagi to'g'ri chiziqlarga parallelligi."}]},
    {'subject_name': 'Geometriya', 'subject_code': 'geometriya', 'grade': 10, 'quarter': 2, 'chapter': 'Perpendikulyarlik fazoda', 'topics': [{'title': "To'g'ri chiziq va tekislikning perpendikulyarligi ta'rifi va alomati", 'objectives': "Tekislikdagi kesishuvchi ikki to'g'ri chiziqqa perpendikulyarlik sharti."}, {'title': "Nuqtadan tekislikka tushirilgan perpendikulyar va og'ma", 'objectives': "Perpendikulyar, og'ma va og'maning proyeksiyasi orasidagi Pifagor munosabati."}, {'title': 'Uch perpendikulyar haqidagi teorema va unga teskari teorema', 'objectives': "Stereometrik masalalarda burchak va masofalarni hisoblashda qo'llash."}, {'title': "To'g'ri chiziq va tekislik orasidagi burchak", 'objectives': "To'g'ri chiziq va uning tekislikdagi proyeksiyasi orasidagi burchakni topish."}, {'title': 'Ikki yoqli burchak va uning chiziqli burchagi', 'objectives': "Ikki yoqli burchakning kattaligini chiziqli burchak orqali o'lchash."}, {'title': 'Tekisliklarning perpendikulyarlik alomati', 'objectives': "Biri ikkinchisiga perpendikulyar to'g'ri chiziqdan o'tuvchi tekisliklar xossasi."}]},
    {'subject_name': 'Geometriya', 'subject_code': 'geometriya', 'grade': 10, 'quarter': 3, 'chapter': 'Fazoda koordinatalar va Vektorlar', 'topics': [{'title': "Fazoda to'g'ri burchakli koordinatalar sistemasi (Oxyz)", 'objectives': "Abskissa, ordinata va applikata o'qlari bo'yicha nuqta koordinatalarini yasash."}, {'title': 'Fazoda ikki nuqta orasidagi masofa formulasi', 'objectives': "d = √((x2-x1)^2 + (y2-y1)^2 + (z2-z1)^2) formulasini qo'llash."}, {'title': "Kesma o'rtasining koordinatalari", 'objectives': "Fazodagi kesmaning o'rta nuqtasini hisoblash."}, {'title': 'Fazoda vektorlar va ular ustida amallar', 'objectives': "Fazoviy vektorlarni qo'shish, songa ko'paytirish va koordinatalarini topish."}, {'title': "Vektorlarning skalyar ko'paytmasi va ikki vektor orasidagi burchak", 'objectives': "Fazoviy burchak kosinusini skalyar ko'paytma orqali aniqlash."}]},
    {'subject_name': 'Geometriya', 'subject_code': 'geometriya', 'grade': 10, 'quarter': 4, 'chapter': "Ko'pyoqlar: Prizma va Parallelepiped", 'topics': [{'title': "Ko'pyoq tushunchasi. Qavariq ko'pyoqlar va Eyler formulasi: V - E + F = 2", 'objectives': "Uchlar, qirralar va yoqlar bog'liqligini tushunish."}, {'title': "Prizma ta'rifi, asoslari va yon yoqlari", 'objectives': "To'g'ri va og'ma prizmalarni farqlash."}, {'title': "Prizmaning yon sirti va to'la sirti yuzi", 'objectives': "S_to'la = S_yon + 2S_asos formulasidan foydalanish."}, {'title': "To'g'ri burchakli parallelepiped va uning diagonali", 'objectives': "d^2 = a^2 + b^2 + c^2 munosabatini masalalarda qo'llash."}]},
    {'subject_name': 'Geometriya', 'subject_code': 'geometriya', 'grade': 11, 'quarter': 1, 'chapter': "Ko'pyoqlar: Piramida va Hajmlar", 'topics': [{'title': "Piramida ta'rifi, uchi, asosi va yon qirralari", 'objectives': 'Piramida balandligi va apofemasi tushunchalarini bilish.'}, {'title': 'Muntazam piramida va uning xossalari', 'objectives': 'Muntazam piramidaning yon sirti yuzi: S = 1/2 P * h_a.'}, {'title': 'Kesiq piramida va uning elementlari', 'objectives': "Parallel tekislik bilan kesilganda hosil bo'lgan kesiq piramidani o'rganish."}, {'title': 'Fazoviy jismlarning hajmi tushunchasi va xossalari', 'objectives': "Hajmlarning tengligi va qo'shiluvchanlik xossalarini bilish."}, {'title': 'Prizma va parallelepipedning hajmi', 'objectives': 'V = S_asos * H formulasidan foydalanib hisoblash.'}, {'title': 'Piramida va kesiq piramidaning hajmi', 'objectives': "V = 1/3 S_asos * H formulasini qo'llash."}]},
    {'subject_name': 'Geometriya', 'subject_code': 'geometriya', 'grade': 11, 'quarter': 2, 'chapter': 'Aylanish jismlari: Silindr va Konus', 'topics': [{'title': "Silindr ta'rifi, o'qi, yasovchisi va asoslari", 'objectives': "To'g'ri to'rtburchakni bir tomoni atrofida aylantirishdan hosil bo'lgan jism."}, {'title': "Silindrning yon sirti, to'la sirti yuzi va hajmi", 'objectives': 'S_yon = 2πRH, V = πR^2H formulalarini bilish.'}, {'title': "Konus ta'rifi, uchi, yasovchisi va asosi", 'objectives': "To'g'ri burchakli uchburchakni kateti atrofida aylantirishdan hosil bo'lishi."}, {'title': "Konusning yon sirti, to'la sirti yuzi va hajmi", 'objectives': "S_yon = πRL, V = 1/3 πR^2H formulalarini qo'llash."}, {'title': 'Kesiq konus va uning yuzasi hamda hajmi', 'objectives': 'Kesiq konus elementlarini aniqlash va hisoblash.'}]},
    {'subject_name': 'Geometriya', 'subject_code': 'geometriya', 'grade': 11, 'quarter': 3, 'chapter': 'Shar va Sfera', 'topics': [{'title': "Sfera va shar ta'riflari. Markaz, radius va diametr", 'objectives': "Yarim doirani diametri atrofida aylantirishdan hosil bo'lishi."}, {'title': 'Sferaga urinuvchi tekislik va uning xossasi', 'objectives': 'Tekislikning sferaga perpendikulyarligi va kesim aylanasi.'}, {'title': 'Sferaning sirti yuzi formulasi: S = 4πR^2', 'objectives': 'Sfera sirtini hisoblash masalalarini yechish.'}, {'title': 'Sharning hajmi formulasi: V = 4/3 πR^3', 'objectives': 'Shar va uning qismlari (shar segmenti, sektori) hajmini hisoblash.'}]},
    {'subject_name': 'Geometriya', 'subject_code': 'geometriya', 'grade': 11, 'quarter': 4, 'chapter': 'Aylanish jismlari kombinatsiyalari va Takrorlash', 'topics': [{'title': "Ko'pyoqlar va aylanish jismlarining kombinatsiyalari", 'objectives': 'Prizmaga ichki va tashqi chizilgan silindrlar.'}, {'title': 'Piramidaga ichki va tashqi chizilgan konus va shar', 'objectives': "Asosiy kesimlar yordamida radius va balandliklarni bog'lash."}, {'title': 'Geometriyadan OTM kirish imtihonlari masalalari tahlili', 'objectives': "Murakkab fazoviy masalalarni chizmalar asosida yechish ko'nikmalari."}, {'title': 'Yillik umumlashtiruvchi takrorlash', 'objectives': 'Stereometriya kursining barcha asosiy teoremalari va formulalarini mustahkamlash.'}]},
    {'subject_name': 'Fizika', 'subject_code': 'fizika', 'grade': 7, 'quarter': 1, 'chapter': 'Fizika asoslari va Mexanik harakat', 'topics': [{'title': "Fizika fani va tabiat hodisalari. Fizik kattaliklar va o'lchov asboblari", 'objectives': "SI sistemasida asosiy birliklar va o'lchov xatoliklarini bilish."}, {'title': 'Moddaning tuzilishi: molekulalar va atomlar. Diffuziya hodisasi', 'objectives': 'Zarralarning uzluksiz harakati va modda holatlarini tushunish.'}, {'title': "Mexanik harakat. Moddiy nuqta, trayektoriya, bosib o'tilgan yo'l", 'objectives': "Yo'l va ko'chish tushunchalarini farqlash."}, {'title': "To'g'ri chiziqli tekis harakat va tezlik. Tezlik birliklari", 'objectives': "v = s / t formulasi bo'yicha hisob-kitoblar bajarish va grafiklar chizish."}, {'title': "Notekis harakat va o'rtacha tezlik", 'objectives': "v_o'rt = s_jami / t_jami formulasi bo'yicha masalalar yechish."}]},
    {'subject_name': 'Fizika', 'subject_code': 'fizika', 'grade': 7, 'quarter': 2, 'chapter': 'Massa, Zichlik va Kuch', 'topics': [{'title': "Inersiya hodisasi. Jismlarning o'zaro ta'siri va massa", 'objectives': "Massaning inersiya o'lchovi ekanligini bilish, tarozida tortish."}, {'title': 'Moddaning zichligi va uning birliklari', 'objectives': "ρ = m / V formulasi bo'yicha zichlik, massa va hajmni topish."}, {'title': "Kuch tushunchasi. Kuchlarni qo'shish va teng ta'sir etuvchi kuch", 'objectives': "Kuchning vektor kattalik ekanligi va dinamometr bilan o'lchash."}, {'title': "Butun olam tortishish qonuni. Og'irlik kuchi va jismning og'irligi", 'objectives': 'F = mg formulasini bilish va vaznsizlik holatini tushunish.'}, {'title': 'Elastiklik kuchi. Guk qonuni', 'objectives': "F_el = k * Δl formulasini qo'llab bikrlik va cho'zilishni hisoblash."}, {'title': 'Ishqalanish kuchi (tinchlikdagi, sirpanish va dumalash ishqalanishi)', 'objectives': "Ishqalanish koeffitsiyenti va texnikada ishqalanishning o'rni."}]},
    {'subject_name': 'Fizika', 'subject_code': 'fizika', 'grade': 7, 'quarter': 3, 'chapter': 'Bosim va Gidrostatika', 'topics': [{'title': 'Bosim tushunchasi. Qattiq jismlarning bosimi va Paskal birligi', 'objectives': "p = F / S formulasini amalda qo'llash."}, {'title': 'Gaz va suyuqliklarda bosimning uzatilishi. Paskal qonuni', 'objectives': 'Gidravlik press va uning ishlash prinsipini bilish.'}, {'title': 'Suyuqlik ustunining bosimi (gidrostatik bosim)', 'objectives': "p = ρgh formulasi bo'yicha tubga va devorga bosimni hisoblash."}, {'title': 'Tutash idishlar qonuni', 'objectives': 'Har xil zichlikdagi suyuqliklar ustunlari balandligini taqqoslash.'}, {'title': 'Atmosfera bosimi. Torrichelli tajribasi va barometr', 'objectives': 'Normal atmosfera bosimi (760 mm sim. ust.) tushunchasini bilish.'}, {'title': "Suyuqlik va gazlarda jismga ta'sir etuvchi kuch. Arximed qonuni", 'objectives': "F_A = ρ_s * g * V_j formulasidan foydalanib ko'tarish kuchini topish."}, {'title': 'Jismlarning suzish shartlari. Kemalar va aerostatlarning suzishi', 'objectives': 'Jism zichligi va suyuqlik zichligi munosabatlarini tahlil qilish.'}]},
    {'subject_name': 'Fizika', 'subject_code': 'fizika', 'grade': 7, 'quarter': 4, 'chapter': 'Ish, Quvvat va Energiya', 'topics': [{'title': 'Mexanik ish va uning birliklari', 'objectives': "A = F * s formulasini qo'llash, ishning musbat, manfiy va nol bo'lish hollarini bilish."}, {'title': 'Quvvat tushunchasi va vatt birligi', 'objectives': 'N = A / t va N = F * v formulalaridan foydalanish.'}, {'title': 'Oddiy mexanizmlar: Richag, blok, qiya tekislik', 'objectives': 'Kuchdan yutish qoidasi va richag muvozanat sharti (M = F * l).'}, {'title': "Mexanikaning 'oltin qoidasi' va Mexanizmning FIK", 'objectives': "η = (A_foydali / A_to'la) * 100% formulasini qo'llash."}, {'title': 'Kinetik va potensial energiya', 'objectives': "E_k = mv^2 / 2 va E_p = mgh formulalari bo'yicha energiyani hisoblash."}, {'title': "To'liq mexanik energiyaning saqlanish qonuni", 'objectives': 'Energiyaning bir turdan boshqasiga aylanishini tushunish.'}]},
    {'subject_name': 'Fizika', 'subject_code': 'fizika', 'grade': 8, 'quarter': 1, 'chapter': 'Issiqlik hodisalari', 'topics': [{'title': 'Issiqlik harakati va harorat. Ichki energiya', 'objectives': "Ichki energiyani o'zgartirish usullari: ish bajarish va issiqlik uzatish."}, {'title': "Issiqlik o'tkazuvchanlik, konveksiya va nurlanish", 'objectives': 'Turli moddalarda issiqlik uzatilish xususiyatlarini tushuntirish.'}, {'title': "Issiqlik miqdori. Solishtirma issiqlik sig'imi", 'objectives': "Q = cm(t2 - t1) formulasi bo'yicha masalalar yechish."}, {'title': "Yonilg'ining yonish issiqligi va solishtirma yonish issiqligi", 'objectives': "Q = q * m formulasi bo'yicha ajraladigan issiqlikni hisoblash."}, {'title': 'Issiqlik balansi tenglamasi', 'objectives': 'Q_olingan = Q_berilgan munosabatidan foydalanib oxirgi haroratni topish.'}]},
    {'subject_name': 'Fizika', 'subject_code': 'fizika', 'grade': 8, 'quarter': 2, 'chapter': "Moddaning agregat holatlari o'zgarishi", 'topics': [{'title': 'Erish va qotish. Solishtirma erish issiqligi', 'objectives': 'Q = λm formulasi va erish grafigini tahlil qilish.'}, {'title': "Bug'lanish va kondensatsiya. Qaynash hodisasi", 'objectives': "Qaynash haroratining bosimga bog'liqligini bilish."}, {'title': "Solishtirma bug' hosil bo'lish issiqligi", 'objectives': "Q = Lm formulasi orqali bug'lanishdagi issiqlikni hisoblash."}, {'title': "Issiqlik dvigatellari (Ichki yonuv dvigateli, bug' turbinasi)", 'objectives': "To'rt taktli dvigatel ishlash bosqichlari va FIK: η = (Q1-Q2)/Q1."}]},
    {'subject_name': 'Fizika', 'subject_code': 'fizika', 'grade': 8, 'quarter': 3, 'chapter': 'Elektr hodisalari va Elektr toki', 'topics': [{'title': 'Elektr zaryadi. Jismlarning elektrlanishi va ikki turdagi zaryad', 'objectives': 'Musbat va manfiy zaryadlar, zaryadning saqlanish qonuni.'}, {'title': "Zaryadlarning o'zaro ta'siri. Kulon qonuni", 'objectives': "F = k * (|q1||q2|) / r^2 formulasi bo'yicha o'zaro ta'sir kuchini topish."}, {'title': 'Elektr toki va uning manbalari. Elektr zanjiri', 'objectives': 'Erkin zaryadlarning tartibli harakati, zanjir sxemalarini chizish.'}, {'title': 'Tok kuchi va ampermetr: I = q / t', 'objectives': "Tok kuchini o'lchash va ampermetrni ketma-ket ulash qoidasi."}, {'title': 'Elektr kuchlanish va voltmetr: U = A / q', 'objectives': "Kuchlanishni o'lchash va voltmetrni parallel ulash qoidasi."}, {'title': "O'tkazgichning elektr qarshiligi. Solishtirma qarshilik", 'objectives': 'R = ρ * l / S formulasidan foydalanib qarshilikni hisoblash.'}]},
    {'subject_name': 'Fizika', 'subject_code': 'fizika', 'grade': 8, 'quarter': 4, 'chapter': 'Om qonuni va Elektr tokining ishi', 'topics': [{'title': 'Zanjir qismi uchun Om qonuni: I = U / R', 'objectives': "Tok kuchi, kuchlanish va qarshilik orasidagi bog'lanishni tekshirish."}, {'title': "O'tkazgichlarni ketma-ket ulash qoidalari", 'objectives': "I = const, U = U1 + U2, R = R1 + R2 munosabatlarini qo'llash."}, {'title': "O'tkazgichlarni parallel ulash qoidalari", 'objectives': 'U = const, I = I1 + I2, 1/R = 1/R1 + 1/R2 formulalarini bilish.'}, {'title': 'Elektr tokining ishi va quvvati', 'objectives': "A = IUt va P = UI formulalari bo'yicha quvvatni hisoblash."}, {'title': 'Joul-Lens qonuni: Q = I^2 * R * t', 'objectives': "Tok o'tganda ajraladigan issiqlik miqdorini aniqlash."}, {'title': 'Qisqa tutashuv va saqlagichlar', 'objectives': 'Xavfsizlik qoidalari va xonadonda elektr energiyasini hisobga olish (kVt*soat).'}]},
    {'subject_name': 'Fizika', 'subject_code': 'fizika', 'grade': 9, 'quarter': 1, 'chapter': 'Kinematika', 'topics': [{'title': 'Tekis tezlanuvchan harakat va tezlanish: a = (v - v0) / t', 'objectives': 'Tezlanish formulasidan foydalanib harakat turini aniqlash.'}, {'title': "Tekis tezlanuvchan harakatda tezlik va ko'chish tenglamalari", 'objectives': "v = v0 + at va s = v0*t + at^2/2 formulalarini qo'llash."}, {'title': "Erkin tushish harakati. Og'irlik kuchi tezlanishi g = 9.8 m/s^2", 'objectives': 'Yuqoriga otilgan va balandlikdan tushayotgan jismlar harakatini hisoblash.'}, {'title': "Jismning aylana bo'ylab tekis harakati", 'objectives': 'Chiziqli tezlik, burchakli tezlik (ω), aylanish davri (T) va chastotasi (ν).'}, {'title': 'Markazga intilma tezlanish: a = v^2 / r', 'objectives': "Aylanma harakatdagi tezlanish yo'nalishi va kattaligini topish."}]},
    {'subject_name': 'Fizika', 'subject_code': 'fizika', 'grade': 9, 'quarter': 2, 'chapter': 'Dinamika', 'topics': [{'title': 'Nyutonning birinchi qonuni. Inersial sanoq sistemalari', 'objectives': 'Galiley nisbiylik prinsipi va inersiyani tushunish.'}, {'title': 'Nyutonning ikkinchi qonuni: F = ma', 'objectives': "Kuch, massa va tezlanish bog'liqligini masalalarda qo'llash."}, {'title': 'Nyutonning uchinchi qonuni: F1 = -F2', 'objectives': "Ta'sir va aks ta'sir kuchlarining tengligi va qarama-qarshi yo'nalganligi."}, {'title': "Jism impulsining va kuch impulsining ta'rifi: p = mv, FΔt = Δp", 'objectives': "Impuls o'zgarishi va kuch orasidagi munosabatni bilish."}, {'title': 'Impulsning saqlanish qonuni va Reaktiv harakat', 'objectives': "Yopiq sistemada jismlar to'qnashuvi va raketalar harakatini hisoblash."}]},
    {'subject_name': 'Fizika', 'subject_code': 'fizika', 'grade': 9, 'quarter': 3, 'chapter': "Mexanik tebranishlar va To'lqinlar", 'topics': [{'title': 'Erkin va majburiy tebranishlar. Tebranish parametrlari', 'objectives': 'Amplituda, davr, chastota va siklik chastota.'}, {'title': 'Matematik va prujinali mayatniklar', 'objectives': "T = 2π√(l/g) va T = 2π√(m/k) formulalarini qo'llash."}, {'title': 'Rezonans hodisasi', 'objectives': 'Majburiy tebranish chastotasi xususiy chastotaga tenglashganda amplituda keskin oshishi.'}, {'title': "Ko'ndalang va bo'ylama to'lqinlar. To'lqin uzunligi va tezligi: v = λν", 'objectives': "Muhitda to'lqin tarqalishi qonuniyatlari."}, {'title': "Tovush to'lqinlari. Tovush balandligi, tembri va qattiqligi. Exolokatsiya", 'objectives': 'Infratovush va ultratovush xususiyatlarini bilish.'}]},
    {'subject_name': 'Fizika', 'subject_code': 'fizika', 'grade': 9, 'quarter': 4, 'chapter': 'Elektromagnit maydon va Optika asoslari', 'topics': [{'title': 'Doimiy magnitlar va magnit maydoni. Magnit chiziqlari', 'objectives': 'Magnit qutblari (N va S) va yerning magnit maydonini bilish.'}, {'title': "Tokli o'tkazgichning magnit maydoni. O'ng parma qoidasi", 'objectives': "Magnit induksiya chiziqlari yo'nalishini aniqlash."}, {'title': "Yorug'likning to'g'ri chiziq bo'ylab tarqalishi va soya hodisasi", 'objectives': "Yorug'lik nuri, quyosh va oy tutilishini tushuntirish."}, {'title': "Yorug'likning qaytish qonuni va Yassi ko'zgu", 'objectives': "Tushish burchagi qaytish burchagiga tengligi va tasvir hosil bo'lishi."}, {'title': "Yorug'likning sinish qonuni va To'liq ichki qaytish", 'objectives': "Sinish ko'rsatkichi n = sin α / sin β va optik tolalarda qo'llanishi."}, {'title': 'Yupqa linzalar va linza formulasi: 1/F = 1/d + 1/f', 'objectives': "Yig'uvchi va sochuvchi linzalarda nurlar yo'li va tasvir yasash."}]},
    {'subject_name': 'Fizika', 'subject_code': 'fizika', 'grade': 10, 'quarter': 1, 'chapter': 'Molekulyar fizika va Termodinamika', 'topics': [{'title': 'Molekulyar-kinetik nazariya (MKN) asosiy qoidalari va tajribaviy asoslari', 'objectives': 'Modda miqdori, molyar massa va Avogadro soni (N_A).'}, {'title': 'Ideal gaz modeli. Ideal gaz MKN asosiy tenglamasi: p = 1/3 n m0 v^2', 'objectives': "Bosim va molekulalar o'rtacha kinetik energiyasi bog'lanishi (p = nkT)."}, {'title': "Absolyut harorat shkalasi (Kelvin). Gaz bosimining haroratga bog'liqligi", 'objectives': 'T = t + 273 munosabatidan foydalanish.'}, {'title': 'Ideal gaz holat tenglamasi (Mendeleyev-Klapeyron tenglamasi): pV = (m/M)RT', 'objectives': 'Universal gaz doimiysi R = 8.31 J/(mol*K) bilan hisoblash.'}, {'title': 'Izojarayonlar: Izotermik jarayon (Boyl-Mariott qonuni: pV = const)', 'objectives': 'Izotermik jarayon grafiklarini (p-V, p-T, V-T) tahlil qilish.'}, {'title': 'Izobarik jarayon (Gey-Lyussak qonuni) va Izoxorik jarayon (Sharl qonuni)', 'objectives': "V/T = const va p/T = const qonunlarini qo'llash."}, {'title': 'Termodinamika asoslari. Termodinamikaning birinchi qonuni: Q = ΔU + A', 'objectives': "Gazning bajargan ishi (A = pΔV) va ichki energiya o'zgarishini topish."}, {'title': "Adiabatik jarayon. Q = 0 da tashqi kuchlar ishi hisobiga energiya o'zgarishi", 'objectives': "Issiqlik izolyatsiyalangan tizimda harorat o'zgarishi."}]},
    {'subject_name': 'Fizika', 'subject_code': 'fizika', 'grade': 10, 'quarter': 2, 'chapter': 'Suyuqliklar va Qattiq jismlar xossalari', 'topics': [{'title': "To'yingan va to'yinmagan bug'lar. Qaynash va kritik harorat", 'objectives': "Bug' bosimining haroratga bog'liqligi va dinamik muvozanat."}, {'title': 'Havoning namligi: Absolyut va nisbiy namlik. Psixrometr', 'objectives': 'Nisbiy namlik formulasi va inson hayotidagi ahamiyati.'}, {'title': 'Suyuqliklarning sirt taranglik hodisasi va sirt taranglik koeffitsiyenti', 'objectives': 'F = σ * l formulasidan foydalanib sirt kuchini hisoblash.'}, {'title': "Ho'llash va ho'llamaslik. Kapillyar hodisalar", 'objectives': "Kapillyarda suyuqlik ko'tarilish balandligi h = 2σ / (ρgr)."}, {'title': 'Qattiq jismlarning tuzilishi: Kristall va amorf moddalar. Anizotropiya', 'objectives': 'Kristall panjaralar turlarini farqlash.'}, {'title': 'Qattiq jismlarning mexanik deformatsiyalari va elastiklik moduli (Yung moduli)', 'objectives': "Mexanik kuchlanish σ = E * ε formulasini qo'llash."}]},
    {'subject_name': 'Fizika', 'subject_code': 'fizika', 'grade': 10, 'quarter': 3, 'chapter': 'Elektrostatika', 'topics': [{'title': 'Elektr maydoni. Elektr maydon kuchlanganligi: E = F / q', 'objectives': 'Nuqtaviy zaryad maydon kuchlanganligi E = k * q / r^2.'}, {'title': 'Maydonlarning superpozitsiya prinsipi', 'objectives': "Bir nechta zaryad maydon kuchlanganliklarini vektor qo'shish."}, {'title': 'Elektr maydon kuch chiziqlari. Bir jinsli elektr maydoni', 'objectives': 'Kuch chiziqlari musbatdan chiqib manfiyga kirishini bilish.'}, {'title': "Zaryadni elektr maydonida ko'chirishda bajarilgan ish. Potensial va Potensiallar farqi", 'objectives': "A = q(φ1 - φ2) = qU va E = U / d munosabatlarini qo'llash."}, {'title': "O'tkazgichlar va dielektriklar elektr maydonida. Qutblanish", 'objectives': 'Dielektrik singdiruvchanlik ε va elektrostatik himoya.'}, {'title': "Elektr sig'imi va Kondensatorlar. Yassi kondensator sig'imi: C = εε0S / d", 'objectives': 'Kondensatorlarni ketma-ket va parallel ulash.'}, {'title': 'Zaryadlangan kondensator energiyasi: W = CU^2 / 2', 'objectives': 'Elektr maydon energiyasi zichligini hisoblash.'}]},
    {'subject_name': 'Fizika', 'subject_code': 'fizika', 'grade': 10, 'quarter': 4, 'chapter': 'Doimiy elektr toki qonunlari', 'topics': [{'title': 'Elektr yurituvchi kuch (EYUK) va manbaning ichki qarshiligi', 'objectives': "E = A_begona / q va to'liq zanjir tushunchasi."}, {'title': "To'liq zanjir uchun Om qonuni: I = E / (R + r)", 'objectives': 'Tashqi qarshilik nolga tenglashganda qisqa tutashuv toki (I_qt = E / r).'}, {'title': 'Manbalarni ketma-ket va parallel ulash', 'objectives': 'Batareya EYUK va ichki qarshiligini hisoblash.'}, {'title': "Turli muhitlarda elektr toki: Metallarda elektr o'tkazuvchanlik", 'objectives': "Erkin elektronlar dreyf tezligi va haroratga bog'liqlik."}, {'title': 'Elektrolitlarda elektr toki. Faradeyning elektroliz qonunlari: m = kIt', 'objectives': "Moddaning elektrokimyoviy ekvivalentini bilish va texnikada qo'llash."}, {'title': "Yarimo'tkazgichlarda elektr toki. p-n o'tish va yarimo'tkazgichli diod", 'objectives': "Xususiy va aralashmali o'tkazuvchanlik, to'g'rilagichlar."}, {'title': 'Gazlarda va vakuumda elektr toki. Termoelektron emissiya', 'objectives': 'Mustaqil va nomustaqil gaz razryadlari turlari.'}]},
    {'subject_name': 'Fizika', 'subject_code': 'fizika', 'grade': 11, 'quarter': 1, 'chapter': 'Elektromagnitizm va Elektromagnit induksiya', 'topics': [{'title': 'Magnit maydoni induksiyasi (B) va Amper kuchi: F_A = I B l sin α', 'objectives': "Chap qo'l qoidasi bilan Amper kuchi yo'nalishini topish."}, {'title': 'Lorens kuchi: F_L = q v B sin α. Zaryadlangan zarraning magnit maydonidagi harakati', 'objectives': 'Aylanma trayektoriya radiusi r = mv / (qB) ni hisoblash.'}, {'title': 'Magnit oqimi: Φ = B S cos α va Veber birligi', 'objectives': "Kontur orqali o'tuvchi magnit oqimini hisoblash."}, {'title': 'Elektromagnit induksiya hodisasi. Faradey qonuni: E_i = -ΔΦ / Δt', 'objectives': "Induksiya EYUK ning magnit oqimi o'zgarish tezligiga bog'liqligi."}, {'title': "Lens qoidasi: Induksion tokning yo'nalishi", 'objectives': "Induksion tok o'zining magnit maydoni bilan sababchi oqimga qarshilik ko'rsatishi."}, {'title': "O'zinduksiya hodisasi. Induktivlik va Magnit maydon energiyasi: W = L I^2 / 2", 'objectives': "G'altakning induktivligi va ekstra-toklar."}, {'title': "O'zgaruvchan tok generatori va Transformatorlar: k = U1 / U2 = N1 / N2", 'objectives': "Elektr energiyasini uzoq masofalarga yo'qotishlarsiz uzatish."}]},
    {'subject_name': 'Fizika', 'subject_code': 'fizika', 'grade': 11, 'quarter': 2, 'chapter': "Elektromagnit tebranishlar va To'lqinlar", 'topics': [{'title': 'Tebranish konturi. Erkin elektromagnit tebranishlar', 'objectives': "Kondensator va g'altak zanjirida energiya almashinuvi."}, {'title': 'Tomson formulasi: T = 2π√(LC)', 'objectives': 'Tebranish davri va chastotasini hisoblash.'}, {'title': "Elektromagnit to'lqinlar va Maksvell nazariyasi", 'objectives': "O'zgaruvchan elektr va magnit maydonlarining fazoda tarqalishi (c = 3*10^8 m/s)."}, {'title': "Elektromagnit to'lqinlar shkalasi: Radioto'lqinlardan gamma nurlargacha", 'objectives': "To'lqin uzunligi va chastotasi bo'yicha to'lqinlarni tasniflash."}, {'title': 'Radiologik aloqa prinsiplari. Modulyatsiya va detektorlash. Radar', 'objectives': 'Ochiq tebranish konturi va antenna orqali signal uzatish.'}]},
    {'subject_name': 'Fizika', 'subject_code': 'fizika', 'grade': 11, 'quarter': 3, 'chapter': "To'lqin va Kvant optikasi", 'topics': [{'title': "Yorug'lik interferensiyasi. Kogerent to'lqinlar va interferensiya maksimumi", 'objectives': "Δd = kλ va Δd = (2k+1)λ/2 shartlarini qo'llash."}, {'title': "Yorug'lik difraksiyasi va Difraksion panjara: d sin φ = kλ", 'objectives': "To'siqlarni aylanib o'tish hodisasi va spektr olish."}, {'title': "Yorug'lik qutblanishi va dispersion hodisasi", 'objectives': "Sindirish ko'rsatkichining to'lqin uzunligiga bog'liqligi (kamalak hosil bo'lishi)."}, {'title': 'Issiqlik nurlanishi va Plank gipotezasi. Kvant energiyasi: E = hν', 'objectives': 'Plank doimiysi h = 6.63 * 10^-34 J*s bilan hisoblash.'}, {'title': 'Fotoeffekt hodisasi. Fotoeffekt uchun Eynshteyn tenglamasi: hν = A_chiqish + E_k', 'objectives': 'Fotoeffektning qizil chegarasi: ν_0 = A / h.'}, {'title': 'Fotonning massasi va impulsi: p = h / λ. Kompton effekti', 'objectives': "Yorug'likning korpuskulyar-to'lqin dualizmi."}]},
    {'subject_name': 'Fizika', 'subject_code': 'fizika', 'grade': 11, 'quarter': 4, 'chapter': 'Atom va Yadro fizikasi. Koinot', 'topics': [{'title': 'Atomning tuzilishi. Rezerford tajribasi va Atomning planetar modeli', 'objectives': "Atom yadrosi va elektron qobig'ini tushunish."}, {'title': 'Bor postulatlari va Bor nazariyasi', 'objectives': 'Statsionar orbitalar va foton yutilishi yoki nurlanishi (hν = Em - En).'}, {'title': 'Atom yadrosining tarkibi: Protonlar va neytronlar. Nuklonlar', 'objectives': 'Zaryad soni (Z) va massa soni (A) orqali zarrachalarni topish.'}, {'title': "Yadro kuchlari va Yadroning bog'lanish energiyasi. Massa defekti: ΔE = Δm * c^2", 'objectives': "Solishtirma bog'lanish energiyasini hisoblash."}, {'title': 'Radioaktivlik hodisasi. Alfa, beta va gamma nurlanishlar', 'objectives': 'Radioaktiv yemirilish qonuni: N = N0 * 2^(-t/T).'}, {'title': "Yadro reaksiyalari. Og'ir yadrolarning bo'linishi. Zanjirli yadro reaksiyasi", 'objectives': 'Atom elektr stansiyalari (AES) va ekologik xavfsizlik.'}, {'title': 'Quyosh va yulduzlar energiyasi. Termoyadro sintez reaksiyasi', 'objectives': 'Vodorod yadrolarining geliyga aylanishi va koinot evolyutsiyasi.'}]},
